"""
indodax.py
==================

Python client library for the "Indodax - New Trade API V2"

Covers:
- Get Orders (order history)
- Get Trade History
- Get Account Information
- Get Order Detail
- Create Order (Buy / Sell)
- Cancel Order
- Get Pending Orders (open orders)
- Withdraw Coin (by username / by address)
- Withdraw IDR (fiat)
- Get FIAT Deposit & Withdraw History
- Get Coin Deposit History
- Get Coin Withdraw History
- Get Deposit Address List
- Get Private Websocket Token

Signing scheme (mirrors the Postman pre-request scripts):
1. Build a params dict in a fixed, deliberate order.
2. Append either `nonce` (default) or `timestamp` + `recvWindow`.
3. URL-encode each key/value the same way JS `encodeURIComponent` does,
   join as `key1=val1&key2=val2&...` -> this is the "canonical" string.
4. HMAC-SHA256(secret, canonical) -> hex digest -> `Sign` header.
5. GET/DELETE: canonical string is the query string.
   POST: canonical string is the raw `application/x-www-form-urlencoded` body.

Install dependency:
    pip install requests

Quick start:
    from indodax import IndodaxClient, IndodaxAPIError

    # Set prevent_execution=True untuk testing (POST & DELETE akan di-bypass)
    client = IndodaxClient(
        api_key="YOUR_API_KEY",
        api_secret="YOUR_API_SECRET",
        tapi_key="YOUR_TAPI_KEY",
        tapi_secret="YOUR_TAPI_SECRET",
        base_url="https://api.indodax.com",  # set to the real host
        prevent_execution=True 
    )

    try:
        print(client.get_account())
        print(client.get_orders(symbol="usdtidr", limit=10))
        order = client.create_order_buy(symbol="usdtidr", quantity=3, price=18000)
    except IndodaxAPIError as e:
        print(f"Error pada endpoint {e.endpoint}: {e.payload}")
"""

from __future__ import annotations

import hashlib
import hmac
import json
import time
import urllib.parse
from typing import Any, Dict, Optional

import requests

# encodeURIComponent leaves these characters unescaped; mirror that exactly
# so the canonical string (and therefore the signature) matches what the
# Postman/JS pre-request script would produce.
_URI_COMPONENT_SAFE = "!'()*-._~"


def _encode_uri_component(value: Any) -> str:
    return urllib.parse.quote(str(value), safe=_URI_COMPONENT_SAFE)


class IndodaxAPIError(Exception):
    """Raised when the Indodax API returns a non-2xx response."""

    def __init__(
        self,
        status_code: int,
        payload: Any,
        endpoint: str = "",
        params: Optional[Dict[str, Any]] = None,
    ):
        self.status_code = status_code
        self.payload = payload
        self.endpoint = endpoint
        self.params = params or {}

        # Memformat pesan error agar informatif saat dieksekusi / di-log
        msg = f"Indodax API error {status_code}"
        if endpoint:
            msg += f" [{endpoint}]"
        if params:
            msg += f" Params: {json.dumps(self.params)}"
        msg += f" -> Response: {payload}"

        super().__init__(msg)


class IndodaxClient:
    def __init__(
        self,
        api_key: str,
        api_secret: str,
        base_url: str,
        tapi_key: str = "",       # Parameter baru ditambahkan di sini
        tapi_secret: str = "",    # Parameter baru ditambahkan di sini
        timeout: int = 10,
        session: Optional[requests.Session] = None,
        prevent_execution: bool = False,
    ):
        """
        Args:
            api_key: Your Indodax API key (X-APIKEY / Key header).
            api_secret: Your Indodax API secret, used to HMAC-sign requests.
            base_url: e.g. "https://api.yourexchange.com" (the collection's
                {{indodax}} value — set this to the real host).
            tapi_key: API Key khusus untuk endpoint /tapi lama.
            tapi_secret: API Secret khusus untuk endpoint /tapi lama.
            timeout: Request timeout in seconds.
            session: Optional pre-configured requests.Session to reuse.
            prevent_execution: If True, POST and DELETE requests will be blocked 
                               and return a mock string instead.
        """
        self.api_key = api_key
        self.api_secret = api_secret
        self.tapi_key = tapi_key          # Simpan TAPI key
        self.tapi_secret = tapi_secret    # Simpan TAPI secret
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = session or requests.Session()
        self.prevent_execution = prevent_execution  # Disimpan sebagai atribut class

    # ------------------------------------------------------------------
    # Signing internals
    # ------------------------------------------------------------------
    def _build_canonical(
        self,
        params: Dict[str, Any],
        use_nonce: bool = True,
        recv_window_ms: Optional[int] = None,
    ) -> str:
        params = dict(params)  # copy, preserve insertion order (py3.7+)
        now = int(time.time() * 1000)
        if use_nonce:
            params["nonce"] = now
        else:
            params["timestamp"] = now
            if recv_window_ms is not None:
                params["recvWindow"] = recv_window_ms

        parts = []
        for key, value in params.items():
            if value is None:
                value = ""
            elif isinstance(value, (dict, list)):
                value = json.dumps(value)
            parts.append(f"{_encode_uri_component(key)}={_encode_uri_component(value)}")
        return "&".join(parts)

    def _sign(self, canonical: str) -> str:
        return hmac.new(
            self.api_secret.encode("utf-8"),
            canonical.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()

    def _prepare(
        self,
        params: Dict[str, Any],
        use_nonce: bool = True,
        recv_window_ms: Optional[int] = None,
    ):
        canonical = self._build_canonical(params, use_nonce, recv_window_ms)
        sign = self._sign(canonical)
        return canonical, sign

    # ------------------------------------------------------------------
    # HTTP helpers
    # ------------------------------------------------------------------
    def _handle_response(
        self,
        resp: requests.Response,
        endpoint: str = "",
        params: Optional[Dict[str, Any]] = None,
    ) -> Any:
        try:
            data = resp.json()
        except ValueError:
            data = resp.text
        if not resp.ok:
            raise IndodaxAPIError(
                status_code=resp.status_code,
                payload=data,
                endpoint=endpoint,
                params=params,
            )
        return data

    def _get(self, path: str, params: Dict[str, Any], key_header: str = "X-APIKEY") -> Any:
        # Filter parameter: abaikan jika valuenya string kosong ("") atau None
        params = {k: v for k, v in params.items() if v != "" and v is not None}

        canonical, sign = self._prepare(params)
        url = f"{self.base_url}{path}"
        if canonical:
            url = f"{url}?{canonical}"
        headers = {key_header: self.api_key, "Sign": sign}
        resp = self.session.get(url, headers=headers, timeout=self.timeout)
        return self._handle_response(resp, endpoint=path, params=params)

    def _delete(self, path: str, params: Dict[str, Any], key_header: str = "X-APIKEY") -> Any:
        # Filter parameter: abaikan jika valuenya string kosong ("") atau None
        params = {k: v for k, v in params.items() if v != "" and v is not None}
        
        url = f"{self.base_url}{path}"
        
        # Blokir eksekusi jika prevent_execution = True
        if self.prevent_execution:
            return {
                "data": None,
                "code": 200, 
                "msg": f"request has prevent to call endpoint {url} with parameter {json.dumps(params)}"
            }
        
        canonical, sign = self._prepare(params)
        if canonical:
            url = f"{url}?{canonical}"
        headers = {key_header: self.api_key, "Sign": sign}
        resp = self.session.delete(url, headers=headers, timeout=self.timeout)
        return self._handle_response(resp, endpoint=path, params=params)

    def _post(self, path: str, params: Dict[str, Any], key_header: str = "X-APIKEY") -> Any:
        # Filter parameter: abaikan jika valuenya string kosong ("") atau None
        params = {k: v for k, v in params.items() if v != "" and v is not None}
        
        url = f"{self.base_url}{path}"
        
        # Blokir eksekusi jika prevent_execution = True
        if self.prevent_execution:
            return {
                "data": None,
                "code": 200,
                "msg": f"request has prevent to call endpoint {url} with parameter {json.dumps(params)}"
            }
        
        canonical, sign = self._prepare(params)
        headers = {
            key_header: self.api_key,
            "Sign": sign,
            "Content-Type": "application/x-www-form-urlencoded",
        }
        resp = self.session.post(url, data=canonical.encode("utf-8"), headers=headers, timeout=self.timeout)
        return self._handle_response(resp, endpoint=path, params=params)
    
    # ------------------------------------------------------------------
    # Market / account data
    # ------------------------------------------------------------------
    def get_orders(
        self,
        symbol: str,
        start_time: Optional[int] = None,
        end_time: Optional[int] = None,
        limit: int = 10,
        sort: str = "asc",
    ) -> Any:
        """GET /api/v2/order/histories"""
        params: Dict[str, Any] = {"symbol": symbol}
        if start_time is not None:
            params["startTime"] = start_time
        if end_time is not None:
            params["endTime"] = end_time
        params["limit"] = limit
        params["sort"] = sort
        return self._get("/api/v2/order/histories", params)

    def get_trade_history(
        self,
        symbol: str,
        order_id: Optional[str] = None,
        client_order_id: Optional[str] = None,
        start_time: Optional[int] = None,
        end_time: Optional[int] = None,
        limit: int = 10,
        sort: str = "desc",
    ) -> Any:
        """GET /api/v2/myTrades"""
        params: Dict[str, Any] = {"symbol": symbol}
        if order_id is not None:
            params["orderID"] = order_id
        if client_order_id is not None:
            params["clientOrderID"] = client_order_id
        if start_time is not None:
            params["startTime"] = start_time
        if end_time is not None:
            params["endTime"] = end_time
        params["limit"] = limit
        params["sort"] = sort
        return self._get("/api/v2/myTrades", params)

    def get_account(self) -> Any:
        """GET /api/v2/account"""
        return self._get("/api/v2/account", {})

    def get_order_detail(
        self,
        symbol: str,
        order_id: Optional[int] = None,
        orig_client_order_id: Optional[str] = None,
    ) -> Any:
        """GET /api/v2/order"""
        params: Dict[str, Any] = {"symbol": symbol}
        if order_id is not None:
            params["orderID"] = order_id
        if orig_client_order_id is not None:
            params["origClientOrderId"] = orig_client_order_id
        return self._get("/api/v2/order", params)

    def get_pending_orders(self, symbol: str = "") -> Any:
        """GET /api/v2/openOrders (empty symbol = all pairs)"""
        return self._get("/api/v2/openOrders", {"symbol": symbol})

    # ------------------------------------------------------------------
    # Orders
    # ------------------------------------------------------------------
    def create_order(
        self,
        symbol: str,
        side: str,
        order_type: str,
        quantity: Optional[float] = None,
        quote_order_qty: Optional[float] = None,
        price: Optional[float] = None,
        new_client_order_id: str = "",
        self_trade_prevention_mode: str = "",
        time_in_force: str = "",
    ) -> Any:
        """POST /api/v2/order"""
        params: Dict[str, Any] = {
            "symbol": symbol,
            "side": side,
            "quantity": quantity if quantity is not None else 0,
            "quoteOrderQty": quote_order_qty if quote_order_qty is not None else 0,
            "type": order_type,
        }
        if price is not None:
            params["price"] = price
        params["newClientOrderId"] = new_client_order_id
        params["selfTradePreventionMode"] = self_trade_prevention_mode
        params["timeInForce"] = time_in_force
        return self._post("/api/v2/order", params)

    def create_order_buy(
        self,
        symbol: str,
        quantity: Optional[float] = None,
        quote_order_qty: Optional[float] = None,
        order_type: str = "LIMIT",
        price: Optional[float] = None,
        new_client_order_id: str = "",
        self_trade_prevention_mode: str = "EXPIRE_MAKER",
        time_in_force: str = "",
    ) -> Any:
        return self.create_order(
            symbol, "BUY", order_type, quantity, quote_order_qty, price,
            new_client_order_id, self_trade_prevention_mode, time_in_force,
        )

    def create_order_sell(
        self,
        symbol: str,
        quantity: Optional[float] = None,
        quote_order_qty: Optional[float] = None,
        order_type: str = "LIMIT",
        price: Optional[float] = None,
        new_client_order_id: str = "",
        self_trade_prevention_mode: str = "",
        time_in_force: str = "",
    ) -> Any:
        return self.create_order(
            symbol, "SELL", order_type, quantity, quote_order_qty, price,
            new_client_order_id, self_trade_prevention_mode, time_in_force,
        )

    def cancel_order(
        self,
        symbol: str,
        order_id: Optional[int] = None,
        orig_client_order_id: Optional[str] = None,
    ) -> Any:
        """DELETE /api/v2/order"""
        params: Dict[str, Any] = {"symbol": symbol}
        if order_id is not None:
            params["orderID"] = order_id
        if orig_client_order_id is not None:
            params["origClientOrderId"] = orig_client_order_id
        return self._delete("/api/v2/order", params)

    # ------------------------------------------------------------------
    # Withdrawals / deposits
    # ------------------------------------------------------------------
    def withdraw_coin_username(
        self,
        coin: str,
        network: str,
        withdraw_username: str,
        amount: str,
        address_tag: str = "",
        withdraw_order_id: str = "",
        address: str = "",
    ) -> Any:
        """POST /api/v2/capital/withdraw/apply (internal transfer by username)"""
        params = {
            "coin": coin,
            "network": network,
            "address": address,
            "withdrawUsername": withdraw_username,
            "amount": amount,
            "addressTag": address_tag,
            "withdrawOrderId": withdraw_order_id,
            "withdrawMethod": "username",
        }
        return self._post("/api/v2/capital/withdraw/apply", params, key_header="Key")

    def withdraw_coin_address(
        self,
        coin: str,
        network: str,
        address: str,
        amount: str,
        username: str = "",
        address_tag: str = "",
        withdraw_order_id: str = "",
    ) -> Any:
        """POST /api/v2/capital/withdraw/apply (on-chain withdrawal to address)"""
        params = {
            "coin": coin,
            "network": network,
            "address": address,
            "username": username,
            "amount": amount,
            "addressTag": address_tag,
            "withdrawOrderId": withdraw_order_id,
            "withdrawMethod": "address",
        }
        return self._post("/api/v2/capital/withdraw/apply", params, key_header="Key")

    def withdraw_idr(
        self,
        amount: str,
        account_number: str,
        bank_code: str,
        api_payment_method: str = "bank_transfer",
        currency: str = "idr",
        client_request_id: str = "",
    ) -> Any:
        """POST /api/v2/fiat/withdraw"""
        params = {
            "amount": amount,
            "apiPaymentMethod": api_payment_method,
            "currency": currency,
            "accountInfo": {"accountNumber": account_number, "bankCodeForPix": bank_code},
            "clientRequestId": client_request_id,
        }
        return self._post("/api/v2/fiat/withdraw", params)

    def get_fiat_history(self, transaction_type: int, begin_time: int, end_time: int) -> Any:
        """GET /api/v2/fiat/orders   transaction_type: 0=deposit, 1=withdraw"""
        params = {"transactionType": transaction_type, "beginTime": begin_time, "endTime": end_time}
        return self._get("/api/v2/fiat/orders", params)

    def get_coin_deposit_history(
        self,
        coin: str = "",
        start_time: Optional[int] = None,
        end_time: Optional[int] = None,
        limit: int = 100,
        deposit_status: str = "success",
    ) -> Any:
        """GET /api/v2/capital/deposit/hisrec"""
        params: Dict[str, Any] = {"coin": coin}
        if start_time is not None:
            params["startTime"] = start_time
        if end_time is not None:
            params["endTime"] = end_time
        params["limit"] = limit
        params["depositStatus"] = deposit_status
        return self._get("/api/v2/capital/deposit/hisrec", params)

    def get_coin_withdraw_history(
        self,
        coin: str = "",
        start_time: Optional[int] = None,
        end_time: Optional[int] = None,
        limit: int = 100,
        withdraw_status: str = "",
    ) -> Any:
        """GET /api/v2/capital/withdraw/history"""
        params: Dict[str, Any] = {"coin": coin}
        if start_time is not None:
            params["startTime"] = start_time
        if end_time is not None:
            params["endTime"] = end_time
        params["limit"] = limit
        params["withdrawStatus"] = withdraw_status
        return self._get("/api/v2/capital/withdraw/history", params)

    def get_deposit_address_list(self, coin: str, network: str = "") -> Any:
        """GET /api/v2/capital/deposit/address/list"""
        params = {"coin": coin, "network": network}
        return self._get("/api/v2/capital/deposit/address/list", params)
    

    # ------------------------------------------------------------------
    # TAPI (Legacy Endpoint) Helpers
    # ------------------------------------------------------------------
    def _sign_tapi(self, data: str) -> str:
        """
        Endpoint /tapi menggunakan SHA512, berbeda dengan V2 yang menggunakan SHA256.
        """
        sign = hmac.new(
            self.tapi_secret.encode("utf-8"),  # Menggunakan TAPI secret
            data.encode("utf-8"), 
            hashlib.sha512
        )
        return sign.hexdigest()

    # ------------------------------------------------------------------
    # Websocket Token
    # ------------------------------------------------------------------
    def get_private_ws_token(self) -> Optional[Dict[str, str]]:
        """
        POST https://indodax.com/tapi
        Mengambil koneksi token dan channel untuk Private Websocket.
        """
        url = "https://indodax.com/tapi"
        
        # Endpoint /tapi pada Indodax selalu membutuhkan parameter 'method'
        parameters = {
            'method': 'get_ws_token',
            'client': 'tapi',
            'tapi_key': self.tapi_key,         # Menggunakan TAPI key
            'nonce': int(time.time() * 1000)
        }
        
        # Encode URL seperti yang diminta oleh endpoint lama
        query_string = urllib.parse.urlencode(parameters)
        
        headers = {
            'Key': self.tapi_key,              # Menggunakan TAPI key pada header
            'Sign': self._sign_tapi(query_string)
        }
        
        # Karena ini tidak masuk ke base_url API V2, kita panggil requests / session langsung 
        # (Melewati self._post V2 karena format signature & penanganan response-nya berbeda)
        try:
            response = self.session.post(
                url, 
                headers=headers, 
                data=parameters, 
                timeout=self.timeout
            )
            
            if response.status_code == 200:
                data = response.json()
                if data.get('success') == 1:
                    return {
                        'token': data['return']['connToken'], 
                        'channel': data['return']['channel']
                    }
                else:
                    print(f"API Error Get WS Token: {data.get('error')}")
                    return None    
            else:
                print(f"HTTP Error Get WS Token {response.status_code}: {response.text}")
                return None
        except Exception as e:
            print(f"Exception during Get WS Token: {e}")
            return None